// Keep the original bytes available without fetch or ES modules, including file://.
import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const blocks = {};
for (let index = 0; index < 6; index++) {
  const name = `DATA.00${index}`;
  blocks[name] = (await readFile(new URL(`assets/${name}`, root))).toString('base64');
}
await writeFile(new URL('assets-data.js', root),
  '// Generated by tools/build-assets.mjs from the original packed blocks.\n' +
  `globalThis.DEMO1996_DATA = ${JSON.stringify(blocks, null, 2)};\n`);
